        return 1                       # the end: one route is complete
    total = 0
    seen[row][col] = True              # mark
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = row + dr, col + dc
        if 0 <= nr < r and 0 <= nc < c and grid[nr][nc] == "." and not seen[nr][nc]:
            total += count(nr, nc)
    seen[row][col] = False             # unmark: leave no trace
    return total

